#!/usr/bin/env python3
"""Apply to 0.766 after updating note prototypes; preserves the rest of HTML."""
from pathlib import Path
import subprocess,sys
p=Path(sys.argv[1]);subprocess.run([sys.executable,str(Path(__file__).with_name('patch-b39-doubled-voicings.py')),str(p)],check=True);s=p.read_text()
def r(a,b):
 global s
 if s.count(a)!=1:raise SystemExit('expected one match: '+a[:100])
 s=s.replace(a,b,1)
r("    return {type:id,subdivision:2,swing:swing,steps:base,autoGenerated:true,autoSwing:true,autoVariation:variation};", "    return {type:id,subdivision:2,swing:swing,steps:base,autoGenerated:true,autoSwing:true,autoVariation:variation,...(previous && Number.isInteger(previous.noteVariation)?{noteVariation:previous.noteVariation}:{})};")
r("      var prepared=selected.map(function(sec){return {sec:sec,result:HOST.StruChordNoteCandidate.prepare(sec,next,HOST.StruChordNoteCandidate.seedFor(sec,next.trackId))};});", """      var prepared=selected.map(function(sec){var N=HOST.StruChordNoteCandidate,previous=T().patternFor(next.trackId,'s:'+sec.id),start=previous && previous.autoGenerated===true ? N.variationOf(previous)+1 : 0;return {sec:sec,result:N.prepareVariation(sec,next,start)};});""")
r("if(prepared.some(function(x){return !x.result.ok;})){if(HOST.showToast)HOST.showToast(shape.checked ? 'Не удалось сыграть выбранную форму: проверьте размах, диапазон и переходы между аккордами' : 'Не удалось создать партию: проверьте аккорды, размер и диапазон');return;}", "if(prepared.some(function(x){return !x.result.ok;})){if(HOST.showToast)HOST.showToast(prepared.some(function(x){return x.result.reason==='no-distinct-variation';}) ? 'Не удалось создать отличающийся рисунок без изменения настроек' : shape.checked ? 'Не удалось сыграть выбранную форму: проверьте размах, диапазон и переходы между аккордами' : 'Не удалось создать партию: проверьте аккорды, размер и диапазон');return;}")
r("if(pattern){T().setPattern(dialogTrack,'s:'+sec.id,pattern);T().setBassRole(dialogTrack,sec.id,'auto');next.managed[String(sec.id)]=true;}", "if(pattern){var generated=prepared.find(function(x){return x.sec===sec;});if(generated && generated.result.writes.length)pattern.noteVariation=generated.result.variation;T().setPattern(dialogTrack,'s:'+sec.id,pattern);T().setBassRole(dialogTrack,sec.id,'auto');next.managed[String(sec.id)]=true;}")
r("      close();if(HOST.showToast)HOST.showToast('Автоаккомпанемент обновлён');", "      var anyGenerated=prepared.some(function(x){return x.result.writes.length>0;});close();if(HOST.showToast)HOST.showToast(anyGenerated?'Автоаккомпанемент обновлён':'Нет доступных ячеек для генерации; ручные рисунки сохранены');")
p.write_text(s)
